#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n <= 1) {
        printf("%d\n", n);
        return 0;
    }

    int *head = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    int m = 2 * (n - 1);
    int *to = (int *)malloc((m + 1) * sizeof(int));
    int *nxt = (int *)malloc((m + 1) * sizeof(int));

    int ec = 0;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        to[ec] = b;
        nxt[ec] = head[a];
        head[a] = ec++;

        to[ec] = a;
        nxt[ec] = head[b];
        head[b] = ec++;
    }

    int *parent = (int *)malloc((n + 1) * sizeof(int));
    int *order = (int *)malloc((n + 1) * sizeof(int));
    int *stack = (int *)malloc((n + 1) * sizeof(int));

    int top = 0, ord = 0;
    stack[top++] = 1;
    parent[1] = 0;

    while (top > 0) {
        int u = stack[--top];
        order[ord++] = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (v == parent[u]) continue;
            parent[v] = u;
            stack[top++] = v;
        }
    }

    int *sub = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) {
        sub[i] = 1;
    }

    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        if (parent[u] != 0) {
            sub[parent[u]] += sub[u];
        }
    }

    int best = n;
    for (int u = 2; u <= n; u++) {
        int diff = n - 2 * sub[u];
        if (diff < 0) diff = -diff;
        if (diff < best) best = diff;
    }

    printf("%d\n", best);

    free(head);
    free(to);
    free(nxt);
    free(parent);
    free(order);
    free(stack);
    free(sub);

    return 0;
}
